  p.line(8, 12, 5, 14, darken(P.greenD, 0.4)); p.line(9, 12, 12, 14, darken(P.greenD, 0.4)); // 尾鰭下擺
  p.line(8, 12, 8, 14, P.leafL); p.px(6, 14, P.toxic); p.px(11, 14, P.toxic);
